-- Discrete Structures — Assignment 4 (Real)  (10 questions, from quiz-real-discrete-assignment-4.json)
WITH q AS (
  INSERT INTO public.quizzes (title, description, subject, department, year, status, source_type, duration_seconds)
  SELECT 'التركيبات المنفصلة — الواجب 4 (حقيقي)', '{"description":"Real questions extracted verbatim from downloads/discrete-structures/Assignment_4.pdf (pages p1-3). Every answer is determined by the exercise itself (standard discrete-mathematics facts, each computed and double-checked); wrong options are constructed.","department":"AI","year":"المستوى الثاني","subject":"التركيبات المنفصلة","semester":"1"}', 'التركيبات المنفصلة', 'AI', 'المستوى الثاني', 'approved', 'manual', 600
  WHERE NOT EXISTS (SELECT 1 FROM public.quizzes WHERE title = 'التركيبات المنفصلة — الواجب 4 (حقيقي)')
  RETURNING id
)
INSERT INTO public.quiz_questions (quiz_id, question, options, correct_answer, explanation, order_index)
SELECT q.id, v.question, v.options, v.correct_answer, v.explanation, v.order_index
FROM q, (VALUES
  ('Does 17 divide 68?', '["Yes","No","Only with remainder","Cannot be determined"]'::jsonb, 0, '68 = 4 × 17. — المصدر: Assignment_4.pdf، صin-file exercise Q1a', 1),
  ('Does 17 divide 84?', '["No","Yes","Yes, twice","Cannot be determined"]'::jsonb, 1, '17 × 4 = 68, 17 × 5 = 85 → 84 is not a multiple. — المصدر: Assignment_4.pdf، صin-file exercise Q1b', 2),
  ('What are the quotient and remainder when 19 is divided by 7?', '["q = 2, r = 5","q = 2, r = 4","q = 3, r = −2","q = 1, r = 12"]'::jsonb, 0, '19 = 7·2 + 5 with 0 ≤ r < 7. — المصدر: Assignment_4.pdf، صin-file exercise Q3a', 3),
  ('What are the quotient and remainder when −1 is divided by 3?', '["q = −1, r = 2","q = 0, r = −1","q = −1, r = −2","q = 1, r = −4"]'::jsonb, 0, '−1 = 3·(−1) + 2 with 0 ≤ r < 3. — المصدر: Assignment_4.pdf، صin-file exercise Q3g', 4),
  ('Evaluate −17 mod 2.', '["1","−1","0","8"]'::jsonb, 0, '−17 = 2·(−9) + 1 → remainder 1. — المصدر: Assignment_4.pdf، صin-file exercise Q6a', 5),
  ('Evaluate −101 mod 13.', '["3","−10","−3","10"]'::jsonb, 0, '−101 = 13·(−8) + 3 → 3. — المصدر: Assignment_4.pdf، صin-file exercise Q6c', 6),
  ('Evaluate 199 mod 19.', '["9","10","8","1"]'::jsonb, 0, '199 = 19·10 + 9. — المصدر: Assignment_4.pdf، صin-file exercise Q6d', 7),
  ('Determine whether 29 is prime.', '["Yes","No","Only odd primes qualify","Cannot be determined"]'::jsonb, 0, '29 has no divisors except 1 and 29 → prime. — المصدر: Assignment_4.pdf، صin-file exercise Q10b', 8),
  ('Determine whether 143 is prime.', '["No","Yes","Only if 11 ∤ 143","Cannot be determined"]'::jsonb, 0, '143 = 11 × 13 → composite. — المصدر: Assignment_4.pdf، صin-file exercise Q10f', 9),
  ('Use the Euclidean algorithm to find gcd(123, 277).', '["1","3","31","41"]'::jsonb, 0, '277=2·123+31; 123=3·31+30; 31=1·30+1; 30=30·1 → gcd 1. — المصدر: Assignment_4.pdf، صin-file exercise Q15c', 10)
) AS v(question, options, correct_answer, explanation, order_index);

-- Discrete Structures — Assignment 5 (Real)  (8 questions, from quiz-real-discrete-assignment-5.json)
WITH q AS (
  INSERT INTO public.quizzes (title, description, subject, department, year, status, source_type, duration_seconds)
  SELECT 'التركيبات المنفصلة — الواجب 5 (حقيقي)', '{"description":"Real questions extracted verbatim from downloads/discrete-structures/Assignment_5.pdf (pages p1-2). Every answer is determined by the exercise itself (standard discrete-mathematics facts, each computed and double-checked); wrong options are constructed.","department":"AI","year":"المستوى الثاني","subject":"التركيبات المنفصلة","semester":"1"}', 'التركيبات المنفصلة', 'AI', 'المستوى الثاني', 'approved', 'manual', 480
  WHERE NOT EXISTS (SELECT 1 FROM public.quizzes WHERE title = 'التركيبات المنفصلة — الواجب 5 (حقيقي)')
  RETURNING id
)
INSERT INTO public.quiz_questions (quiz_id, question, options, correct_answer, explanation, order_index)
SELECT q.id, v.question, v.options, v.correct_answer, v.explanation, v.order_index
FROM q, (VALUES
  ('P(n): 1² + 2² + … + n² = n(n + 1)(2n + 1)/6. What is the statement P(1)?', '["1² = 1(1 + 1)(2·1 + 1)/6","1² + 2² = 1(2)(3)/6","1 = 6","1² = n(n + 1)(2n + 1)/6 for all n"]'::jsonb, 0, 'Substituting n = 1 into the closed form gives the basis-step statement. — المصدر: Assignment_5.pdf، صin-file exercise Q1a', 1),
  ('P(n): 1³ + 2³ + … + n³ = (n(n + 1)/2)². What is the statement P(1)?', '["1³ = (1·2/2)²","1³ + 2³ = (1·2/2)²","1 = 4","1³ = (n(n+1)/2)² for all n"]'::jsonb, 0, 'Substituting n = 1. — المصدر: Assignment_5.pdf، صin-file exercise Q2a', 2),
  ('P(n): n! < nⁿ for integers n > 1. What is the statement P(2)?', '["2! < 2²","1! < 1¹","2! ≤ 2²","n! < nⁿ for n = all integers"]'::jsonb, 0, 'Substituting n = 2: 2 < 4. — المصدر: Assignment_5.pdf، صin-file exercise Q9a', 3),
  ('Postage of n cents from 3-cent and 5-cent stamps (P(n) true for n ≥ 8). Which shows P(8)?', '["8 = 3 + 5","8 = 3 + 3 + 2","8 = 5 + 5","8 = 3 + 3 + 3"]'::jsonb, 0, 'One 3-cent and one 5-cent stamp make 8. — المصدر: Assignment_5.pdf، صin-file exercise Q11a', 4),
  ('Postage from 4-cent and 7-cent stamps (P(n) for n ≥ 18). Which decomposition shows P(18)?', '["18 = 4 + 7 + 7","18 = 4 + 4 + 4 + 7","18 = 4 + 4 + 4 + 4 + 4","18 = 7 + 7 + 7"]'::jsonb, 0, '4 + 7 + 7 = 18 uses only 4s and 7s. — المصدر: Assignment_5.pdf، صin-file exercise Q12a', 5),
  ('Find a formula for the sum of the first n even positive integers.', '["n(n + 1)","n(n + 1)/2","2n(n + 1)","n²"]'::jsonb, 0, '2(1 + 2 + … + n) = 2·n(n+1)/2 = n(n + 1). — المصدر: Assignment_5.pdf، صin-file exercise Q7a', 6),
  ('For 1·1! + 2·2! + … + n·n! = (n + 1)! − 1: what does the left side equal for n = 3?', '["23","22","24","20"]'::jsonb, 0, '1 + 4 + 18 = 23 = 4! − 1. — المصدر: Assignment_5.pdf، صin-file exercise Q4 (n=3 check)', 7),
  ('For 1² + 3² + 5² + … + (2n + 1)² = (n + 1)(2n + 1)(2n + 3)/3: what is the basis step at n = 0?', '["1² = (0 + 1)(2·0 + 1)(2·0 + 3)/3","1² = 0","1 + 3 = 4","The formula needs n ≥ 1"]'::jsonb, 0, 'n = 0 gives 1 = 1·1·3/3 = 1. — المصدر: Assignment_5.pdf، صin-file exercise Q3 (n=0 basis)', 8)
) AS v(question, options, correct_answer, explanation, order_index);

