INSERT INTO public.quiz_questions (quiz_id, question, options, correct_answer, explanation, order_index)
SELECT q.id, v.question, v.options, v.correct_answer, v.explanation, v.order_index
FROM q, (VALUES
  ('What is a proposition?', '["A declarative sentence that is either True or False, but not both","Any question that can be answered","Any sentence containing a variable","A sentence that is always True"]'::jsonb, 0, 'Section 1, p3 (verbatim): a proposition is a declarative sentence that is either True (T) or False (F), but not both. — المصدر: section_1.pdf، صp3', 1),
  ('Which of the following is NOT a proposition?', '["\"x + 5 = 10\" (x is undefined — an open sentence)","\"2 + 3 = 7\"","\"Assiut is a city in Egypt.\"","\"Python is a programming language.\""]'::jsonb, 0, 'Section 1, p4 (verbatim): "x + 5 = 10" is an open sentence (variable undefined); questions, commands, and paradoxes are also non-propositions. — المصدر: section_1.pdf، صp4', 2),
  ('When is the conjunction p ∧ q true?', '["Only when both p and q are True","When at least one is True","When both are False","When exactly one is True"]'::jsonb, 0, 'Section 1, p7 (verbatim): conjunction is True ONLY when both p and q are True. — المصدر: section_1.pdf، صp7', 3),
  ('When is the disjunction p ∨ q false?', '["Only when both p and q are False","When at least one is True","When both are True","Never"]'::jsonb, 0, 'Section 1, p8 (verbatim): disjunction is False ONLY when both are False (inclusive OR allows both True). — المصدر: section_1.pdf، صp8', 4),
  ('When is the exclusive OR p ⊕ q true?', '["When exactly one of p and q is True","When both are True","When both are False","Always"]'::jsonb, 0, 'Section 1, p9 (verbatim): XOR is True when exactly one is True; False when both True or both False. — المصدر: section_1.pdf، صp9', 5),
  ('The conditional p → q is false ONLY when:', '["p is True and q is False","p is False and q is True","both are False","both are True"]'::jsonb, 0, 'Section 1, p10 (verbatim): p → q is False ONLY when p is True and q is False. — المصدر: section_1.pdf، صp10', 6),
  ('What is the contrapositive of p → q?', '["¬q → ¬p","q → p","¬p → ¬q","p ∧ q"]'::jsonb, 0, 'Section 1, p12 (verbatim): converse q → p; contrapositive ¬q → ¬p; inverse ¬p → ¬q. — المصدر: section_1.pdf، صp12', 7),
  ('A conditional statement is logically equivalent to:', '["Its contrapositive","Its converse","Its inverse","Its negation"]'::jsonb, 0, 'Section 1, p12 (verbatim): (p → q) ≡ (¬q → ¬p); converse and inverse are equivalent to each other but NOT to the original. — المصدر: section_1.pdf، صp12', 8),
  ('The biconditional p ↔ q is true when:', '["p and q have the same truth value","p and q have different truth values","p is true","q is false"]'::jsonb, 0, 'Section 1, p13 (verbatim): p ↔ q is True when p and q have the same truth value; p ↔ q ≡ (p → q) ∧ (q → p). — المصدر: section_1.pdf، صp13', 9),
  ('Which operator has the HIGHEST precedence, and which the LOWEST?', '["¬ highest; biconditional lowest","∨ highest; ¬ lowest","→ highest; ∧ lowest","∧ highest; ∨ lowest"]'::jsonb, 0, 'Section 1, p15 (verbatim table): ¬ (1), ∧ (2), ∨ (3), → (4), biconditional (5, lowest). — المصدر: section_1.pdf، صp15', 10),
  ('An UNSATISFIABLE compound proposition is exactly:', '["A contradiction","A tautology","A contingency","A biconditional"]'::jsonb, 0, 'Section 1, p17 (verbatim): a proposition is Unsatisfiable if and only if it is a Contradiction; tautologies and contingencies are satisfiable. — المصدر: section_1.pdf، صp17', 11),
  ('Which rule describes the dual transformation s*?', '["Interchange ∨ with ∧ and T with F, without changing variables or negations","Negate every variable","Swap every variable with its negation","Replace → with ↔ only"]'::jsonb, 0, 'Section 1, p20 (verbatim): replace ∨↔∧, T↔F; do NOT change variables (¬p stays ¬p). — المصدر: section_1.pdf، صp20', 12),
  ('Which gates are the universal gates?', '["NAND and NOR","AND and OR","XOR and XNOR","NOT and AND"]'::jsonb, 0, 'Section 1, p28 (verbatim): universal gates can construct any logical function without needing any other gate type (NAND, NOR). — المصدر: section_1.pdf، صp28', 13),
  ('The XNOR gate outputs 1 when:', '["The inputs are identical","The inputs are different","Exactly one input is 1","Both inputs are 0"]'::jsonb, 0, 'Section 1, p27 (verbatim): XNOR (equivalence gate) outputs 1 when inputs are identical; ¬(p ⊕ q). — المصدر: section_1.pdf، صp27', 14),
  ('Why does predicate logic go beyond propositional logic?', '["It breaks statements into subjects and predicates, capturing internal structure propositional logic treats as independent variables","It removes the need for truth values","It only works on finite domains","It replaces quantifiers with truth tables"]'::jsonb, 0, 'Section 2, p3 (verbatim): propositional logic treats "All humans are mortal..." as independent variables P, Q, R, failing to capture the valid logical structure. — المصدر: section_2.pdf، صp3', 15),
  ('For P(x) = "x² = 2", which truth values hold over Z vs R?', '["False for all x over Z; True for x = √2 over R","True over both","False over both","True over Z, false over R"]'::jsonb, 0, 'Section 2, p5 (verbatim): truth value heavily depends on the defined domain. — المصدر: section_2.pdf، صp5', 16),
  ('To prove ∀x P(x) is FALSE, you must:', '["Find a single counterexample a such that P(a) is False","Show P(x) is true for one x","Check every element","Assume it is false"]'::jsonb, 0, 'Section 2, p7 (verbatim): to prove False, find a single counterexample. — المصدر: section_2.pdf، صp7', 17),
  ('Over a finite domain D = {0, 1, 2}, ∃x P(x) expands to:', '["P(0) ∨ P(1) ∨ P(2)","P(0) ∧ P(1) ∧ P(2)","¬P(0) ∨ ¬P(2)","P(0) → P(2)"]'::jsonb, 0, 'Section 2, p9 (verbatim): ∃ expands to disjunction; ∀ expands to conjunction. — المصدر: section_2.pdf، صp9', 18),
  ('The golden rule for restricting subsets: which connective pairs with which quantifier?', '["∀ pairs with →; ∃ pairs with ∧","∀ pairs with ∧; ∃ pairs with →","Both pair with ∨","Both pair with ↔"]'::jsonb, 0, 'Section 2, p10 (verbatim): use → with universal quantifiers and ∧ with existential quantifiers. — المصدر: section_2.pdf، صp10', 19),
  ('What is ¬∀x P(x) equivalent to?', '["∃x ¬P(x)","∀x ¬P(x)","∃x P(x)","∀x P(x)"]'::jsonb, 0, 'Section 2, p11 (verbatim De Morgan): ¬∀x P(x) ≡ ∃x ¬P(x) and ¬∃x P(x) ≡ ∀x ¬P(x). — المصدر: section_2.pdf، صp11', 20),
  ('An argument is VALID when:', '["The conclusion must be true whenever all premises are true (the argument form is a tautology)","All premises are true","The conclusion is true","At least one premise is true"]'::jsonb, 0, 'Section 2, p13 (verbatim). — المصدر: section_2.pdf، صp13', 21),
  ('Inferring Q → P from P → Q is the fallacy of:', '["Affirming the consequent","Modus ponens","Modus tollens","Denying the antecedent"]'::jsonb, 0, 'Section 2, p14 (verbatim): valid paths are P→Q (modus ponens) and ¬Q→¬P (modus tollens); Q→P and ¬P→¬Q are fallacies. — المصدر: section_2.pdf، صp14', 22),
  ('How is ∅ different from {∅}?', '["∅ has no elements; {∅} is a set containing one element (the empty set)","They are identical","{∅} has no elements","∅ has one element"]'::jsonb, 0, 'Section 3, p5 (verbatim important distinction). — المصدر: section_3.pdf، صp5', 23),
  ('If |A| = n, how many elements does the power set P(A) contain?', '["2ⁿ","n²","2n","n!"]'::jsonb, 0, 'Section 3, p6 (verbatim golden rule): |P(A)| = 2ⁿ. — المصدر: section_3.pdf، صp6', 24),
  ('What is P({1, 2})?', '["{∅, {1}, {2}, {1, 2}}","{{1}, {2}}","{1, 2}","{∅, 1, 2}"]'::jsonb, 0, 'Section 3, p7 (verbatim step-by-step example). — المصدر: section_3.pdf، صp7', 25),
  ('A is a PROPER subset of B when:', '["A ⊆ B and A ≠ B","A = B","A ⊆ B only","A has more elements than B"]'::jsonb, 0, 'Section 3, p9 (verbatim). — المصدر: section_3.pdf، صp9', 26),
  ('What is the cardinality of the Cartesian product |A × B|?', '["|A| × |B|","|A| + |B|","|A| − |B|","max(|A|, |B|)"]'::jsonb, 0, 'Section 3, p12 (verbatim). — المصدر: section_3.pdf، صp12', 27),
  ('If A = {1, 2, 3} and B = {3, 4, 5}, what is A ∪ B and A ∩ B?', '["{1, 2, 3, 4, 5} and {3}","{3} and {1, 2, 3, 4, 5}","{1, 2, 4, 5} and {3}","{1, 2, 3} and {4, 5}"]'::jsonb, 0, 'Section 3, p13-14 (verbatim examples). — المصدر: section_3.pdf، صp13-14', 28),
  ('If A = {1, 2, 3, 4} and B = {3, 4, 5, 6}, what are A − B and B − A?', '["{1, 2} and {5, 6}","{5, 6} and {1, 2}","{3, 4} and {3, 4}","{1, 2} and {3, 4}"]'::jsonb, 0, 'Section 3, p16 (verbatim example). — المصدر: section_3.pdf، صp16', 29),
  ('A relation is NOT a function when:', '["An element of A has more than one output, or has no output at all","Two elements of A map to the same element of B","The codomain is larger than the domain","The range equals the codomain"]'::jsonb, 0, 'Section 3, p22 (verbatim note). — المصدر: section_3.pdf، صp22', 30),
  ('An injective (one-to-one) function satisfies:', '["If f(a₁) = f(a₂), then a₁ = a₂","Every element of B is mapped to","It always has an inverse","f(x) = f(x) for all x"]'::jsonb, 0, 'Section 3, p23 (verbatim mathematical condition). — المصدر: section_3.pdf، صp23', 31),
  ('An onto (surjective) function satisfies:', '["Range = Codomain (every element of B is mapped to by at least one element of A)","Each codomain element is hit at most once","Domain = Codomain","It has an inverse"]'::jsonb, 0, 'Section 3, p24 (verbatim). — المصدر: section_3.pdf، صp24', 32),
  ('Which type of function possesses an inverse function?', '["Bijective (one-to-one correspondence)","Injective only","Surjective only","Any function"]'::jsonb, 0, 'Section 3, p24 (verbatim): the bijective function is the only type that possesses an inverse function. — المصدر: section_3.pdf، صp24', 33),
  ('Given f(x) = x + 2 and g(x) = x², what is (f ∘ g)(3)?', '["11","25","5","9"]'::jsonb, 0, 'Section 3, p27 (verbatim board example): g(3) = 9, then f(9) = 11. — المصدر: section_3.pdf، صp27', 34),
  ('Which of these divisibility facts is TRUE?', '["17 | 68 but 17 ∤ 84 (68 = 17 × 4; 84 = 17 × 4 + 16)","17 | 84 but 17 ∤ 68","17 divides both 68 and 84","17 divides neither"]'::jsonb, 0, 'Section 4, p2 (verbatim quick examples). — المصدر: section_4.pdf، صp2', 35),
  ('(Multiplicative property) If a | c and b | d, then:', '["ab | cd","a | d","b | c","a + b | c + d"]'::jsonb, 0, 'Section 4, p3 (verbatim properties) with the p4 proof: cd = (ab)(k₁k₂). — المصدر: section_4.pdf، صp3-4', 36),
  ('In the division algorithm a = dq + r, what are the constraints on r?', '["0 ≤ r < d","0 < r ≤ d","r can be any integer","r = d"]'::jsonb, 0, 'Section 4, p5 (verbatim theorem). — المصدر: section_4.pdf، صp5', 37),
  ('Dividing −111 by 11 correctly gives:', '["q = −11, r = 10 (the remainder must be non-negative)","q = −10, r = −1","q = −10, r = 1","q = 11, r = −10"]'::jsonb, 0, 'Section 4, p6 (verbatim): −111 = 11 × (−11) + 10; the negative-remainder attempt is the common student mistake. — المصدر: section_4.pdf، صp6', 38),
  ('14 mod 12 = ?', '["2","14","−2","12"]'::jsonb, 0, 'Section 4, p7 (verbatim clock analogy): 9 + 5 = 14, and on a 12-hour clock it wraps to 2. — المصدر: section_4.pdf، صp7', 39),
  ('Is 17 ≡ 5 (mod 6) true?', '["Yes — 17 mod 6 = 5 = 5 mod 6, and 6 | (17 − 5)","No — the remainders differ","No — 17 is not divisible by 6","Only if we use the equation method"]'::jsonb, 0, 'Section 4, p9 (verbatim): all three methods confirm True. — المصدر: section_4.pdf، صp9', 40),
  ('If ac ≡ bc (mod m), when may we cancel c to conclude a ≡ b (mod m)?', '["Only when gcd(c, m) = 1","Always","Never","When c is even"]'::jsonb, 0, 'Section 4, p10 (verbatim note): division is not defined the same way; cancellation needs gcd(c, m) = 1. — المصدر: section_4.pdf، صp10', 41),
  ('Why is 1 not a prime number?', '["It has only one positive divisor; the definition requires exactly two distinct divisors","It is even","It is negative","It has three divisors"]'::jsonb, 0, 'Section 4, p12 (verbatim). — المصدر: section_4.pdf، صp12', 42),
  ('Which is the only even prime number?', '["2","0","4","There is none"]'::jsonb, 0, 'Section 4, p13 (verbatim): 2 is the only even prime; every other even number is divisible by 2. — المصدر: section_4.pdf، صp13', 43),
  ('Trial-division primality testing checks divisors from 2 up to:', '["√N","N/2","N − 1","log₂ N"]'::jsonb, 0, 'Section 4, p14 (verbatim optimization rule). — المصدر: section_4.pdf، صp14', 44),
  ('The prime factorization of 60 is:', '["2² · 3 · 5","2 · 3 · 5","2³ · 3 · 5","2² · 3² · 5"]'::jsonb, 0, 'Section 4, p18 (verbatim): 60 = 2² · 3 · 5. — المصدر: section_4.pdf، صp18', 45),
  ('gcd(24, 36) and lcm(24, 36) are:', '["12 and 72","72 and 12","6 and 144","4 and 36"]'::jsonb, 0, 'Section 4, p19-20 (verbatim): 24 = 2³·3, 36 = 2²·3²; gcd takes lowest powers = 2²·3 = 12; lcm takes highest = 2³·3² = 72. — المصدر: section_4.pdf، صp19-20', 46),
  ('For positive integers A and B, which identity holds?', '["A × B = GCD(A, B) × LCM(A, B)","A + B = GCD + LCM","A × B = GCD + LCM","A − B = GCD − LCM"]'::jsonb, 0, 'Section 4, p21 (verbatim). — المصدر: section_4.pdf، صp21', 47),
  ('The two core steps of a mathematical induction proof are:', '["Basis step (verify P(n₀)) and inductive step (show P(k) → P(k+1))","Hypothesis and contradiction","Divide and conquer","Basis and conclusion only"]'::jsonb, 0, 'Section 5, p3 (verbatim). — المصدر: section_5.pdf، صp3', 48),
  ('What is the inductive hypothesis in ordinary induction?', '["Assume P(k) is true for an arbitrary integer k ≥ n₀","Assume P(k+1) is true","Assume P(n) is false","Assume all cases are true"]'::jsonb, 0, 'Section 5, p3 (verbatim). — المصدر: section_5.pdf، صp3', 49),
  ('The summation formula proved by induction in the deck is:', '["1 + 2 + ... + n = n(n+1)/2","1 + 2 + ... + n = n²","1 + 2 + ... + n = (n²+n+1)/3","1 + 2 + ... + n = 2ⁿ − 1"]'::jsonb, 0, 'Section 5, p5-6 (verbatim example 1). — المصدر: section_5.pdf، صp5-6', 50),
  ('Strong induction differs from ordinary induction because its inductive hypothesis assumes:', '["P(j) is true for ALL values from the base case up to k","Only P(k) is true","P(k+1) is true","P(n₀) only"]'::jsonb, 0, 'Section 5, p8 (verbatim): assume P(j) true for all n₀ ≤ j ≤ k. — المصدر: section_5.pdf، صp8', 51)
) AS v(question, options, correct_answer, explanation, order_index);

-- OOP — Sheet 1 (Real)  (9 questions, from quiz-real-oop-sheet-1.json)
WITH q AS (
  INSERT INTO public.quizzes (title, description, subject, department, year, status, source_type, duration_seconds)
  SELECT 'البرمجة الكائنية — الشيت 1 (حقيقي)', '{"description":"Real questions extracted verbatim from the Drive sheet downloads/oop/PracticeSheet_1.pdf (pages p1). Correct answers are grounded in the sheet/answer files; wrong options are constructed. Replace nothing — this is the actual course content.","department":"AI","year":"المستوى الثاني","subject":"البرمجة الكائنية","semester":"1"}', 'البرمجة الكائنية', 'AI', 'المستوى الثاني', 'approved', 'manual', 540
  WHERE NOT EXISTS (SELECT 1 FROM public.quizzes WHERE title = 'البرمجة الكائنية — الشيت 1 (حقيقي)')
  RETURNING id
)
INSERT INTO public.quiz_questions (quiz_id, question, options, correct_answer, explanation, order_index)
SELECT q.id, v.question, v.options, v.correct_answer, v.explanation, v.order_index
FROM q, (VALUES
  ('Write a Java program to print ''Hello'' on screen and your name on a separate line. What is the expected output?', '["Hello\nAlexandra Abramov","Hello Alexandra Abramov","Alexandra Abramov\nHello","Hello\n\nAlexandra Abramov"]'::jsonb, 0, 'The sheet prints the expected output: Hello, then the name on a separate line. — المصدر: PracticeSheet_1.pdf، ص1', 1),
  ('Write a program that generates the following table (single print statement). Which table is correct?', '["1990 135\n1991 7290\n1992 11300\n1993 16200","1990 135\n1991 7209\n1992 11300\n1993 16200","1990 135\n1991 7290\n1992 11030\n1993 16200","1990 135\n1991 7290\n1992 11300\n1993 12600"]'::jsonb, 0, 'Verbatim from Sheet 1 Q2. — المصدر: PracticeSheet_1.pdf، ص1', 2),
  ('Write a C++ program to print the following shape (Q3). Which output is required?', '["********\n********\n********\n********","********\n********\n********","********\n********\n********\n********\n********","***\n***\n***\n***"]'::jsonb, 0, 'Verbatim shape from Sheet 1 Q3. — المصدر: PracticeSheet_1.pdf، ص1', 3),
  ('Write a C++ program to print the following shape (Q4). Which output is required?', '[" *\n **\n ***\n *****"," *\n **\n ***\n ****","*****\n ***\n **\n *","*\n**\n***\n****"]'::jsonb, 0, 'Verbatim shape from Sheet 1 Q4. — المصدر: PracticeSheet_1.pdf، ص1', 4),
  ('Write a C++ program to print the following shape (Q5). Which output is required?', '[" *\n ***\n *****\n *******"," *\n **\n ***\n *******"," *******\n *****\n ***\n *"," *\n ***\n ****\n *******"]'::jsonb, 0, 'Verbatim shape from Sheet 1 Q5. — المصدر: PracticeSheet_1.pdf، ص1', 5),
  ('Write a C++ program to print the shape in Q4 using one print statement. Which output must it produce?', '[" *\n **\n ***\n *****"," *\n ***\n *****\n *******","********\n********\n********\n********"," *\n **\n ***\n **"]'::jsonb, 0, 'Q6 requires the exact Q4 shape, produced with one print statement. — المصدر: PracticeSheet_1.pdf، ص1', 6),
  ('Write a C++ program to print the shape in Q5 using one print statement. Which output must it produce?', '[" *\n ***\n *****\n *******"," *\n **\n ***\n *****"," *\n ***\n *****"," *******\n *****\n ***\n *"]'::jsonb, 0, 'Q7 requires the exact Q5 shape. — المصدر: PracticeSheet_1.pdf، ص1', 7),
  ('Write a C++ program to print the following shape (Q8). Which output is required?', '[" *\n ***\n *****\n *******\n ******\n ***\n *"," *\n ***\n *****\n *******"," *\n **\n ***\n ****\n ***\n **\n *"," *\n ***\n *****\n *******\n *****\n ***\n *"]'::jsonb, 0, 'Verbatim diamond shape from Sheet 1 Q8. — المصدر: PracticeSheet_1.pdf، ص1', 8),
  ('Write a C++ program to print the shape in Q8 using one print statement. Which output must it produce?', '[" *\n ***\n *****\n *******\n ******\n ***\n *"," *\n ***\n *****\n *******","********\n********\n********\n********"," *\n **\n ***\n *****\n ***\n **\n *"]'::jsonb, 0, 'Q9 requires the exact Q8 shape. — المصدر: PracticeSheet_1.pdf، ص1', 9)
) AS v(question, options, correct_answer, explanation, order_index);

-- OOP — Sheet 2 (Real)  (10 questions, from quiz-real-oop-sheet-2.json)
WITH q AS (
  INSERT INTO public.quizzes (title, description, subject, department, year, status, source_type, duration_seconds)
  SELECT 'البرمجة الكائنية — الشيت 2 (حقيقي)', '{"description":"Real questions extracted verbatim from the Drive sheet downloads/oop/PracticeSheet_2.pdf + answer files (Eng/Mohamed Alqady, Eng/Walled) (pages p1). Correct answers are grounded in the sheet/answer files; wrong options are constructed. Replace nothing — this is the actual course content.","department":"AI","year":"المستوى الثاني","subject":"البرمجة الكائنية","semester":"1"}', 'البرمجة الكائنية', 'AI', 'المستوى الثاني', 'approved', 'manual', 600
  WHERE NOT EXISTS (SELECT 1 FROM public.quizzes WHERE title = 'البرمجة الكائنية — الشيت 2 (حقيقي)')
  RETURNING id
)
INSERT INTO public.quiz_questions (quiz_id, question, options, correct_answer, explanation, order_index)
SELECT q.id, v.question, v.options, v.correct_answer, v.explanation, v.order_index
FROM q, (VALUES
  ('Write a Java program to read two numbers and an operation: +, -, *, or / and print the result. Which core solution is correct?', '["if (op==''+'') print(num1+num2);\nelse if (op==''-'') print(num1-num2);\nelse if (op==''*'') print(num1*num2);\nelse if (op==''/'') { if (num2==0) print(\"Sorry can''t devide by 0\"); else print(num1/num2); }","if (op==''+'') print(num1+num2);\nelse if (op==''-'') print(num1-num2);\nelse if (op==''*'') print(num1*num2);\nelse print(num1/num2);","if (op==''+'' || op==''-'' || op==''*'' || op==''/'') print(num1 op num2);\nelse print(\"invalid\");","switch (num1) { case ''+'': print(num2+num1); break; ... }"]'::jsonb, 0, 'Verbatim core of the accepted solution (Sheet_2_Q1.java, Eng/Mohamed Alqady). — المصدر: PracticeSheet_2.pdf، ص1', 1),
  ('Repeat the calculator but ask the user if he/she wants to make another calculation (''y'' = repeat, else end). Which core loop is correct?', '["while (true){ ...calculation...; char repeat=input.next().charAt(0); if (repeat!=''y''&&repeat!=''Y'') break; }","do { ...calculation...; } while (true);","while (repeat == ''y'') { ...calculation...; }","for (;;) { if (repeat == ''n'') continue; ...calculation...; }"]'::jsonb, 0, 'Verbatim core of the accepted solution (Sheet_2_Q2.java + answers-walled_3.txt). — المصدر: PracticeSheet_2.pdf، ص1', 2),
  ('Write a Java program to compute the sum of all integers from 1 to any given integer. Which core solution is correct?', '["int sum=0;\nif (num>0) for (int i=1;i<=num;i++) sum+=i;\nelse for (int i=-1;i>=num;i--) sum+=i;","int sum=0;\nfor (int i=1;i<=num;i++) sum+=i;","int sum=0;\nfor (int i=0;i<num;i++) sum+=i;","int sum=1;\nfor (int i=1;i<num;i++) sum*=i;"]'::jsonb, 0, 'Verbatim core of the accepted solution (Sheet_2_Q3.java; also answers-walled_1-2.txt). — المصدر: PracticeSheet_2.pdf، ص1', 3),
  ('Write a Java program to read two integers and print all odd integers between them. Which core loop is correct?', '["for (int i=theSmallest;i<=theBiggest;i++) if (i%2!=0) print(i+\" \");","for (int i=theSmallest;i<=theBiggest;i++) if (i%2==0) print(i+\" \");","for (int i=num1;i<num2;i+=2) print(i+\" \");","while (num1<num2) print(num1%2+\" \");"]'::jsonb, 0, 'Verbatim core of the accepted solution (Sheet_2_Q4.java). — المصدر: PracticeSheet_2.pdf، ص1', 4),
  ('Write a Java program to read integers x and y, then compute the sum of squares of integers from x to y. Which core loop is correct?', '["for (int i=theSmallest;i<=theBiggest;i++) sum+=(long)i*i;","for (int i=theSmallest;i<=theBiggest;i++) sum+=i;","for (int i=theSmallest;i<=theBiggest;i++) sum+=(long)(i+i);","for (int i=num1;i<=num2;i++) sum+=i*i*i;"]'::jsonb, 0, 'Verbatim core of the accepted solution (Sheet_2_Q5.java). — المصدر: PracticeSheet_2.pdf، ص1', 5),
  ('Write a Java program to find the maximum/minimum of a set of numbers (0 ends input). Which core logic is correct?', '["theBiggest=num; theSmallest=num;\nwhile (true){ num=input.nextInt(); if (num==0) break;\ntheBiggest=theBiggest>num?theBiggest:num; theSmallest=theSmallest<num?theSmallest:num; }","theBiggest=0; theSmallest=0;\nwhile (num!=0){ theBiggest=num; theSmallest=num; }","theBiggest=Math.max();\nfor (...) theBiggest=Math.max(theBiggest,0);","for (...) { theBiggest=num; } print(theBiggest);"]'::jsonb, 0, 'Verbatim core of the accepted solution (Sheet_2_Q6.java). — المصدر: PracticeSheet_2.pdf، ص1', 6),
  ('Write a Java program to compute x^y for any given two integers x and y. Which core loop is correct?', '["if (pow>=1) for (int i=1;i<=pow;i++) power*=num;\nelse for (int i=-1;i>=pow;i--) power*=(double)1/num;","for (int i=1;i<=pow;i++) power+=num;","for (int i=1;i<=num;i++) power*=pow;","power = num ** pow;"]'::jsonb, 0, 'Verbatim core of the accepted solution (Sheet_2_Q7.java; also answers-walled_power.txt). — المصدر: PracticeSheet_2.pdf، ص1', 7),
  ('Write a Java program to compute the factorial of any given integer. Which core loop is correct?', '["long fact=1;\nfor (int i=1;i<=num;i++) fact*=(long)i;","long fact=0;\nfor (int i=1;i<=num;i++) fact+=(long)i;","long fact=1;\nfor (int i=1;i<num;i++) fact*=(long)i;","long fact=1;\nfor (int i=num;i>0;i-=2) fact*=(long)i;"]'::jsonb, 0, 'Verbatim core of the accepted solution (Sheet_2_Q8.java; also answers-walled_fact.txt). — المصدر: PracticeSheet_2.pdf، ص1', 8),
  ('Write a Java program to calculate e^x = 1 + x + x²/2! + x³/3! + x⁴/4! … Which core loop is correct?', '["double E=1,term=1;\nfor (int i=1;i<=20;i++){ term=term*x/i; E+=term; }","double E=0,term=1;\nfor (int i=1;i<=20;i++){ term*=x*i; E+=term; }","double E=1;\nfor (int i=1;i<=20;i++) E+=Math.pow(x,i);","double E=1,term=1;\nfor (int i=1;i<=20;i++){ term*=x/i; E+=term; }"]'::jsonb, 0, 'Verbatim core of the accepted solution (Sheet_2_Q9.java): term=term*x/i accumulates x^i/i!. — المصدر: PracticeSheet_2.pdf، ص1', 9),
  ('Write a Java program to calculate sin(x) = x − x³/3! + x⁵/5! − x⁷/7! … Which core loop is correct?', '["term=x;\nfor(int i=2;i<=20;i+=2){ sin+=term; term=term*((-1*(x*x))/(i*y)); y+=2; }\n// x converted to radians first","term=x;\nfor(int i=2;i<=20;i++){ sin+=term; term=term*(x*x/i); }\n// no alternating sign","sin=x;\nfor(int i=3;i<=20;i+=2){ sin-=Math.pow(x,i)/i; }","for(int i=1;i<=20;i++){ sin=Math.sin(x); }"]'::jsonb, 0, 'Verbatim core of the accepted solution (Sheet_2_Q10.java): alternating sign via (−1·x²)/(i·y) with y stepping 3,5,7… — المصدر: PracticeSheet_2.pdf، ص1', 10)
) AS v(question, options, correct_answer, explanation, order_index);

-- OOP — Sheet 3 (Real)  (7 questions, from quiz-real-oop-sheet-3.json)
WITH q AS (
  INSERT INTO public.quizzes (title, description, subject, department, year, status, source_type, duration_seconds)
  SELECT 'البرمجة الكائنية — الشيت 3 (حقيقي)', '{"description":"Real questions extracted verbatim from the Drive sheet downloads/oop/Sheet_3.pdf (pages p1). Correct answers are grounded in the sheet/answer files; wrong options are constructed. Replace nothing — this is the actual course content.","department":"AI","year":"المستوى الثاني","subject":"البرمجة الكائنية","semester":"1"}', 'البرمجة الكائنية', 'AI', 'المستوى الثاني', 'approved', 'manual', 420
  WHERE NOT EXISTS (SELECT 1 FROM public.quizzes WHERE title = 'البرمجة الكائنية — الشيت 3 (حقيقي)')
  RETURNING id
)
INSERT INTO public.quiz_questions (quiz_id, question, options, correct_answer, explanation, order_index)
SELECT q.id, v.question, v.options, v.correct_answer, v.explanation, v.order_index
FROM q, (VALUES
  ('Write a program to print all alphabets from a to z. Which output is required?', '["abcdefghijklmnopqrstuvwxyz","zyxwvutsrqponmlkjihgfedcba","ABCDEFGHIJKLMNOPQRSTUVWXYZ","a c e g i k m o q s u w y"]'::jsonb, 0, 'The task itself defines the output: a to z. — المصدر: Sheet_3.pdf، ص1', 1),
  ('Write a program that generates the following table (using loops). Which table is correct?', '["1990 135\n1991 1350\n1992 13500\n1993 135000","1990 135\n1991 1350\n1992 13500\n1993 1350000","1990 135\n1991 7290\n1992 13500\n1993 135000","1990 1350\n1991 13500\n1992 135000\n1993 1350000"]'::jsonb, 0, 'Verbatim table from Sheet 3 Q2. — المصدر: Sheet_3.pdf، ص1', 2),
  ('Write a program to print the following shape (using loops) — 4 rows of 8 asterisks. Which output is required?', '["********\n********\n********\n********","********\n********\n********","*******\n*******\n*******\n*******","***\n***\n***\n***"]'::jsonb, 0, 'Verbatim shape from Sheet 3 Q3. — المصدر: Sheet_3.pdf، ص1', 3),
  ('Write a program to print the following shape (using loops) — staircase. Which output is required?', '[" *\n **\n ***\n *****"," *\n **\n ***\n ****","*****\n ***\n **\n *","*\n**\n***\n*****"]'::jsonb, 0, 'Verbatim shape from Sheet 3 Q4. — المصدر: Sheet_3.pdf، ص1', 4),
  ('Write a program to print the following shape (using loops) — pyramid. Which output is required?', '[" *\n ***\n *****\n *******"," *\n **\n ***\n *******"," *\n ***\n ****\n *******"," *******\n *****\n ***\n *"]'::jsonb, 0, 'Verbatim shape from Sheet 3 Q5. — المصدر: Sheet_3.pdf، ص1', 5),
  ('Write a program to print reverse alphabets from Z to A. Which output is required?', '["zyxwvutsrqponmlkjihgfedcba","abcdefghijklmnopqrstuvwxyz","ZYXWVUTSRQPONMLKJIHGFEDCBA","z y x w v u t s r q p o n m l k j i h g f e d c b a a"]'::jsonb, 0, 'The task itself defines the output: Z to A (lowercase as in Q1''s alphabet range). — المصدر: Sheet_3.pdf، ص1', 6),
  ('Write a program to print the following shape (using loops) — * ** *** ***** (Q8). Which output is required?', '[" *\n **\n ***\n *****"," *\n ***\n *****\n *******"," *\n **\n ***\n ****","*****\n ***\n **\n *"]'::jsonb, 0, 'Verbatim shape from Sheet 3 Q8. — المصدر: Sheet_3.pdf، ص1', 7)
) AS v(question, options, correct_answer, explanation, order_index);
